"""Task 5: build flicker_report.md from validation.json, sigma_delta_results.json,
alternatives_results.json (all produced by the other scripts)."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import flicker_alternatives as fa  # noqa: E402
import appliance as ap  # noqa: E402


def load(name):
    with open(os.path.join(HERE, name)) as f:
        return json.load(f)


def fmt_peaks(pk, n=2):
    return ', '.join(f'{f:.2f} Hz ({a:.3f} %)' for f, a, *_ in pk[:n]) if pk else '-'


def main():
    val = load('validation.json')
    sd = load('sigma_delta_results.json')
    alt = load('alternatives_results.json')
    meta = sd['meta']
    S = sd['summary']
    rec_f, rec_p = fa.RECOMMENDED
    rec = [s for s in alt['summary'] if s['family'] == rec_f and s['param'] == rec_p][0]
    cur = [s for s in alt['summary'] if s['family'] == 'sd1' and s['param'] == 1][0]
    with open(os.path.join(HERE, 'validation.md'), encoding='utf-8') as f:
        vtab = f.read()
    rect1 = [r for r in val['rect'] if r['hp_order'] == 1 and r['phase_deg'] == 0]
    dev_main = max(abs(r['pst_cpf'] - 1) for r in rect1 if r['cpm'] <= 1620)
    dev_4000 = max(abs(r['pst_cpf'] - 1) for r in val['rect'] if r['cpm'] == 4000 and r['hp_order'] == 1)
    L = []
    a = L.append
    a('# Flicker assessment: triac-switched 1 kW heater vs IEC 61000-3-3\n')
    a('Filament dryer, 230 V / 50 Hz, resistive heater 52.9 ohm switched by a triac at full mains cycles. '
      'All scripts, JSON results and plots are in this folder; every number below is regenerated by '
      '`validate_flickermeter.py`, `flicker_sigma_delta.py`, `flicker_alternatives.py`, `make_report.py`.\n')
    a('## Summary\n')
    a('| item | value |\n|---|---|')
    a(f'| flickermeter validation, rectangular 1...1620 cpm (P_st target 1.00 +/- 5 %) | worst {100*dev_main:.1f} % |')
    a(f'| validation 4000 cpm / 4800 cpm (worst over 8 carrier phases) | {100*dev_4000:+.1f} % / {100*(max(r["pst_cpf"] for r in val["rect"] if r["cpm"]==4800 and r["hp_order"]==1)-1):+.1f} % (see note) |')
    a(f"| current firmware, worst P_st over duty (0.005 grid) | **{S['grid_worst']['pst']:.2f} at duty {S['grid_worst']['duty_cmd']:.3f}** -> FAIL (limit 1.0) |")
    a(f"| current firmware, duties with P_st > 1.0 | {', '.join(f'{x:.3f}-{y:.3f}' for x, y in S['grid_duty_ranges_failing_pst'])} |")
    a(f"| current firmware, duties with P_lt > 0.65 (P_lt = P_st at constant duty) | {', '.join(f'{x:.3f}-{y:.3f}' for x, y in S['grid_duty_ranges_failing_plt'])} |")
    a(f"| recommended: {rec['label']} | worst P_st {rec['pst_worst']:.2f} at duty {rec['duty_at_worst']:.2f}; d_c {rec['d_c_pct_worst']:.2f} %, d_max {rec['d_max_pct_worst']:.2f} % |")
    a('')
    a('## 1. Method\n')
    a('| block | implementation (`flickermeter.py`) |\n|---|---|')
    a('| input | terminal voltage sampled at 4 kHz (40 samples per half cycle) |')
    a('| 1 adaptor | x / sqrt(mean-square), mean square from a first-order LP, tau 27.3 s, initialised at the first cycle |')
    a('| 2 demodulator | squaring |')
    a('| 3 filters | 6th-order Butterworth LP 35 Hz at 4 kHz; decimation 4 -> 1 kHz; Butterworth HP 0.05 Hz (1st order per IEC 61000-4-15 text; 6th order as in the brief also run, see validation); weighting filter k = 1.74802, lambda = 2 pi 4.05981, w1..w4 = 2 pi (9.15494, 2.27979, 1.22535, 21.9), bilinear transform at 1 kHz |')
    a(f"| 4 | squaring + first-order LP tau 300 ms; gain {val['calibration_gain']:.6g} set so that 8.8 Hz sinusoidal modulation, dV/V = 0.250 % p-p gives steady-state mean P_inst = 1.000 |")
    a('| 5 | CPF with 4096 log-spaced classes (linear interpolation in a class) over the 10-min window after a 30 s pre-roll; smoothed percentiles and P_st formula as specified; exact percentiles computed as a cross-check (agree within 0.1 %) |')
    a('| d(t), d_c, d_max, T_max | half-cycle rms; steady state = every half cycle covered by a >= 1 s window with max-min <= 0.4 % of U_n (+/-0.2 % band); d(t) relative to the preceding steady-state level; d_c = difference of adjacent steady states; T_max = longest run with d > 3.3 % |')
    a(f"| electrical model | ideal 230 V source + Zref = 0.40 + j0.25 ohm, heater 52.9 ohm, triac ideal, fires {meta['t_fire_us']:.0f} us after each zero crossing of an 'on' cycle, exact R-L transient; half-cycle rms off {meta['U_off_V']:.2f} V, on {meta['U_on_V']:.2f} V -> step dV/V = {meta['dU_rel_pct']:.3f} % |")
    a('| switching pattern | bit-exact model of the ISR: 16-bit accumulator, increment round(pid_output * 65536), one decision per full cycle, accumulator starts at 0, constant duty over 10 min |')
    a('')
    a('## 2. Validation (IEC 61000-4-15 test points, 230 V / 50 Hz)\n')
    a(vtab)
    a('Notes: the 8.8 Hz sine is the calibration point (mean = 1 by construction; P_inst,max = 1.031 is the 300 ms-filter ripple, inside +/-8 %). '
      'Rectangular points 1...1620 cpm (the band that matters for this appliance) are within +0.1...+2.8 %. '
      '4000 cpm (33.3 Hz) is +2.8...+3.9 % over the carrier phases (inside +/-5 %). 4800 cpm (40 Hz) is +31...+35 % (over carrier phases): the modulation fundamental (40 Hz) is above the 35 Hz low-pass, '
      'and 2/3 of the response comes from the 3rd harmonic of the rectangle (120 Hz) mixing with the 100 Hz term of the squared carrier '
      'into a 20 Hz component (probe: mean P_inst with the whole rectangle 3.29, fundamental only 1.13, 3rd harmonic only 2.15). '
      'That point therefore depends on the exact edge shape / bandwidth of the rectangular test generator and the reference meter, not on the '
      '1...25 Hz path; the dV/V value 4.834 % for 4800 cpm was taken from the brief and could not be checked against the standard here. '
      'The carrier-phase sweep (8 phases) changes 4000/4800 cpm results by < 4 %. The heater patterns have no content above 25 Hz '
      '(per-cycle switching), so this does not affect the results below. Both HP orders give the same conclusions (differences <= 1.7 %).\n')
    a('## 3. Current firmware (first-order sigma-delta, decision every full cycle)\n')
    a('Limits: P_st <= 1.0, P_lt <= 0.65 (constant duty -> P_lt = P_st), d_c <= 3.3 %, d_max <= 4 %, T_max(d > 3.3 %) <= 500 ms.\n')
    a('| pid_output | P_st | P_st / 1.0 | P_lt / 0.65 | d_max (%) | d_c (%) | T_max (s) | changes/min | dominant modulation (weighted) | verdict |')
    a('|---:|---:|---:|---:|---:|---:|---:|---:|---|---|')
    for r in S['listed']:
        a(f"| {r['duty_cmd']:.3f} | {r['pst']:.3f} | {100*r['pst']:.0f} % | {100*r['pst']/0.65:.0f} % | {r['d_max_pct']:.2f} | {r['d_c_pct']:.2f} | "
          f"{r['T_max_s']:.2f} | {r['changes_per_min']:.0f} | {fmt_peaks(r['weighted_peaks_f_hz_amp_pct_wamp'])} | {r['verdict']} |")
    a('')
    a(f"Fine grid (0.005 to 0.995, step 0.005): worst P_st = {S['grid_worst']['pst']:.3f} at duty {S['grid_worst']['duty_cmd']:.3f}; "
      f"P_st <= 1.0 at {100*S['grid_pass_fraction_pst']:.0f} % of the duties, P_lt <= 0.65 at {100*S['grid_pass_fraction_plt']:.0f} % "
      f"(only duty <= {S['grid_duty_ranges_failing_plt'][0][0]-0.005:.3f} or >= {S['grid_duty_ranges_failing_plt'][-1][1]+0.005:.3f}). "
      'd_max = 0.75 % at every duty; d_c = 0 for 0.005...0.98 (the voltage never stays inside +/-0.2 % for 1 s while switching) and 0.75 % for duty >= 0.985 (1 s all-on stretches form a steady state); T_max = 0. The d criteria pass with large margin; '
      'P_st/P_lt is the only failing criterion. Dominant modulation amplitudes are the rms-envelope sinusoidal components in % of U; '
      'the failing duties put 0.1...0.5 % of 5...20 Hz modulation into the region where the weighting filter is 0.4...1.0.\n')
    a('Plots: `plot_pst_current.png` (P_st vs duty), `plot_pinst_example.png` (P_inst: current firmware at duty 0.8, first 3 s; recommended 20 s frame at duty 0.5, first 60 s).\n')
    a('## 4. Alternatives (same hardware, full cycles only)\n')
    a('Duty grid 0.01...0.99 (step 0.01) plus the 15 listed duties. Thermal ripple = peak-to-peak of a first-order thermal response '
      'to the power sequence, in % of the full-power steady-state temperature rise, for chamber time constants 60 / 180 / 300 s '
      '(analytic estimate for a burst of period T at duty d: d(1-d) T / tau). "Slowest power period" = longest time between consecutive burst starts at any duty in the grid.\n')
    a('| pattern | duty step | worst P_st (duty) | median P_st | P_st <= 1.0 all duties | P_st <= 0.8 all | P_lt <= 0.65 all | max changes/min | d_c max (%) | ripple pp tau 60/180/300 s (%) | slowest power period (s) |')
    a('|---|---|---:|---:|:-:|:-:|:-:|---:|---:|---|---:|')
    for s in alt['summary']:
        rp = s['thermal_ripple_pp_pct_worst']
        yn = lambda b: 'yes' if b else 'no'  # noqa: E731
        sp = s['longest_power_period_s_worst']
        name = s['label'] + (' **[recommended]**' if (s['family'], s['param']) == fa.RECOMMENDED else '')
        a(f"| {name} | {s['duty_step']} | {s['pst_worst']:.2f} ({s['duty_at_worst']:.2f}) | {s['pst_median']:.2f} | {yn(s['all_pass_pst_1.0'])} | "
          f"{yn(s['all_pass_0.8'])} | {yn(s['all_pass_plt_0.65'])} | {s['max_changes_per_min']:.0f} | {s['d_c_pct_worst']:.2f} | "
          f"{rp['60']:.2f} / {rp['180']:.2f} / {rp['300']:.2f} | {sp if sp is None else f'{sp:.0f}'} |")
    a('')
    a('Plot: `plot_pst_alternatives.png`.\n')
    a('Observations (from the table):\n')
    a('- No pattern that switches faster than about once per second passes P_st <= 1.0 at all duties (SD with K <= 25, bursts of 1-2 s, 2nd-order SD at K = 1); SD with K = 2...8 and the 2nd-order SD at K = 1 are even worse than the current firmware: '
      'with full-cycle switching the modulation band is only 0...25 Hz, so noise shaping has nowhere to push the energy (the weighting is still 0.25 at 25 Hz), and the 1-bit 2nd-order loop adds limit-cycle tones inside the peak region (duty 0.52: 0.28 % at 10 Hz, 0.22 % at 8 Hz -> P_st 2.41; duty 0.20: 0.29 % at 15 Hz -> 1.26).')
    a('- P_st falls with the number of voltage changes per minute. Fixed-period bursts have at most 2 changes per period at every duty, so their worst case is flat over duty; sigma-delta with long K has the same P_st but an irregular pattern, a long slowest power period and a duty error of up to 3 % within 10 min.')
    a('- Because the dryer runs for hours, P_lt <= 0.65 is the binding limit at steady duty (P_lt = P_st). The 10 s burst (worst 0.68) meets P_st <= 0.8 but not P_lt; 20 s is the shortest period tested that meets P_lt with margin.\n')
    a('## 5. Recommendation\n')
    a('| | current firmware | recommended |\n|---|---|---|')
    a(f"| pattern | {cur['label']} | {rec['label']} |")
    a(f"| worst P_st over duty (0.01 grid + listed) | {cur['pst_worst']:.2f} (duty {cur['duty_at_worst']:.2f}) | {rec['pst_worst']:.2f} (duty {rec['duty_at_worst']:.2f}) |")
    a(f"| margin to P_st 1.0 / P_lt 0.65 | {100*(1-cur['pst_worst']):+.0f} % / {100*(1-cur['pst_worst']/0.65):+.0f} % | {100*(1-rec['pst_worst']):+.0f} % / {100*(1-rec['pst_worst']/0.65):+.0f} % |")
    a(f"| d_c / d_max worst | {cur['d_c_pct_worst']:.2f} % / {cur['d_max_pct_worst']:.2f} % | {rec['d_c_pct_worst']:.2f} % / {rec['d_max_pct_worst']:.2f} % |")
    a(f"| voltage changes per minute (max) | {cur['max_changes_per_min']:.0f} | {rec['max_changes_per_min']:.0f} |")
    a(f"| duty resolution | 1/65536 | per 20 s frame 1/1000 (0.1 %), long-term mean 1/65536 via the carried remainder |")
    rp, rc = rec['thermal_ripple_pp_pct_worst'], cur['thermal_ripple_pp_pct_worst']
    a(f"| chamber ripple pp, tau 60 / 180 / 300 s (% of full-power rise) | {rc['60']:.2f} / {rc['180']:.2f} / {rc['300']:.2f} | {rp['60']:.1f} / {rp['180']:.1f} / {rp['300']:.1f} (e.g. 100 K full-power rise, tau 3 min: {rp['180']:.1f} K pp at duty 0.5) |")
    a(f"| slowest power-modulation period | {cur['longest_power_period_s_worst']:.0f} s | 20 s (fixed) |")
    a('')
    a('Firmware rule (no firmware file was edited):\n')
    a('1. Keep the zero-crossing ISR, the 230 us firing delay, the 150 us gate pulse and firing at both zero crossings of an "on" cycle; keep the existing every-other-zero-crossing decision point.')
    a('2. Replace the per-cycle accumulator decision by a 20 s frame: a cycle counter `cyc` (0...999) advances at each decision point. When `cyc == 0`: latch the current `sd_increment`, do `acc += sd_increment * 1000` (uint32; 65536 * 1000 fits), `n_on = acc >> 16`, `acc &= 0xFFFF`. For `cyc < n_on` set `fire_cycle = true`, otherwise false. Each frame is one block of consecutive "on" cycles followed by one block of "off" cycles, i.e. at most 2 voltage changes per 20 s; the carried remainder keeps the long-term mean duty exact.')
    a('3. The frame length is a cycle count (1000 cycles = 20 s at 50 Hz); 1500 cycles (30 s, worst P_st 0.47) is the next step if more margin is wanted. Do not shorten below 1000 cycles (500 cycles = 10 s fails P_lt at 0.68).')
    a('4. Control side: the actuator now updates every 20 s; the PID can keep running at 4 Hz (only the value latched at frame start is used) but should be retuned for the 20 s sample-and-hold (lower derivative gain / filtered derivative, anti-windup) and the thermocouple reading averaged over the frame so the PID does not chase the 20 s ripple.\n')
    a('## 6. Simplifications and assumptions\n')
    a('| item | simplification |\n|---|---|')
    a('| limits | P_st 1.0, P_lt 0.65, d_c 3.3 %, d_max 4 %, T_max 500 ms and Zref = 0.40 + j0.25 ohm were taken from the text of IEC 61000-3-3 as quoted in the brief; the only local copy is a 21-page preview without the limits clause, so they were not read from a file |')
    a('| flicker test-point values | taken from the brief (IEC 61000-4-15 Table values as quoted); not checked against the standard |')
    a('| constant duty | duty constant for the whole 10 min (worst case steady regulation); the real PID changes the increment every 250 ms; P_lt = P_st |')
    a('| supply / load | ideal sine source, no background flicker; 10 W auxiliary load ignored; heater resistance independent of temperature; triac ideal (no on-state voltage); current carry-over past the voltage zero (about 15 us) ignored |')
    a('| adaptor | first-order 27.3 s mean-square tracker on the sampled waveform (not a half-cycle-rms based adaptor); immaterial for steady 230 V |')
    a('| calibration | gain fixed numerically on the steady-state mean of P_inst for the 8.8 Hz / 0.25 % sine (not on P_inst,max) |')
    a('| classifier | 4096 log classes over [1e-6 * max, max] of each record (adaptive range instead of a fixed range) |')
    a('| d-parameters | half-cycle rms (not 1-cycle rms refreshed every half cycle); steady state detected by a sliding 1 s window with max-min <= 0.4 %; d(t) referenced to the last steady state (2 s of heater-off prepended); no separate "voltage change characteristic" segmentation beyond that |')
    a('| thermal | single first-order chamber model; real heater element and sensor ripple will be larger than the chamber-air ripple if the sensor sits close to the element |')
    a('| statistics | single 10-min window per duty, pattern started 30 s before the window (sigma-delta accumulator from 0) |')
    with open(os.path.join(HERE, 'flicker_report.md'), 'w', encoding='utf-8') as f:
        f.write('\n'.join(L) + '\n')
    print('written flicker_report.md')


if __name__ == '__main__':
    main()
